const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point(-0.819876, 53.083908);
  const buffer_radius_m = 5000; // 5 km radius
  const geometry = point.buffer(buffer_radius_m);

  // Date ranges for comparison, +/- 5 days to get more images
  const date1_start = '2023-12-30';
  const date1_end = '2024-01-09'; // Centered on Jan 4, 2024

  const date2_start = '2021-12-31';
  const date2_end = '2022-01-10'; // Centered on Jan 5, 2022

  const s1_collection_id = 'COPERNICUS/S1_GRD';
  const scale = 10; // Sentinel-1 resolution

  // Function to get and process Sentinel-1 data for a given date range
  const getWaterExtent = (startDate, endDate, geom) => {
    let collection = ee.ImageCollection(s1_collection_id)
      .filterBounds(geom)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VV'))
      .filter(ee.Filter.eq('orbitProperties_pass', 'DESCENDING')) // Use DESCENDING pass for consistency
      .filter(ee.Filter.eq('instrumentMode', 'IW'))
      .map(image => image.select('VV').unitScale(-30, 0)); // Scale to 0-1 range for consistency, or keep dB

    if (collection.size().getInfo() === 0) {
      return null;
    }

    // Reduce collection to a single image using median for robustness
    let image = collection.median();

    // Speckle filtering (simple focal_median) - sometimes not strictly needed for median composite
    // image = image.focal_median(30, 'square', 'pixels'); // Using a larger window for robustness, but might be slow.
    // Let's stick with the median composite, it usually handles speckle well enough.

    // Apply a threshold to detect water. Using a common threshold for VV in dB units.
    // If unitScale was used above, threshold needs to be adjusted.
    // A common threshold for water detection in natural units (linear, after converting from dB)
    // is around 0.0001 (or -30dB), or a threshold on the scaled value.
    // For unitScaled VV band where -30dB is 0 and 0dB is 1, a value of 0.3 could correspond to approx -21dB
    // Let's use a scaled threshold or directly work with dB if scaling is removed.
    // Reverting to direct dB threshold for clarity:
    collection = ee.ImageCollection(s1_collection_id)
      .filterBounds(geom)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VV'))
      .filter(ee.Filter.eq('orbitProperties_pass', 'DESCENDING'))
      .filter(ee.Filter.eq('instrumentMode', 'IW'));

    if (collection.size().getInfo() === 0) {
      return null;
    }
    image = collection.median().select('VV');

    // Threshold for water detection (VV < -18 dB is a common value for open water)
    const waterMask = image.lt(-18);

    // Calculate water area
    const waterAreaImage = waterMask.multiply(ee.Image.pixelArea()).updateMask(waterMask);
    const stats = waterAreaImage.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: geom,
      scale: scale,
      maxPixels: 1e9
    });

    const area_sqm = stats.get('VV').getInfo();
    return {
      area: area_sqm,
      num_images: collection.size().getInfo(),
      pixels: waterMask.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: geom,
        scale: scale,
        maxPixels: 1e9
      }).get('VV').getInfo()
    };
  };

  // 2. Data Acquisition & Check
  const result1 = getWaterExtent(date1_start, date1_end, geometry);
  const result2 = getWaterExtent(date2_start, date2_end, geometry);

  let area1_sqm = null;
  let num_images1 = 0;
  let valid_pixels1 = 0;

  if (result1 === null) {
    console.log(`2024 Images: 0`);
    console.log("No Sentinel-1 data found for 2024 period. Consider widening the date range.");
    console.log("C1");
    return;
  } else {
    area1_sqm = result1.area;
    num_images1 = result1.num_images;
    valid_pixels1 = result1.pixels;
    console.log(`2024 Images: ${num_images1} (Water Pixels: ${valid_pixels1})`);
  }

  let area2_sqm = null;
  let num_images2 = 0;
  let valid_pixels2 = 0;

  if (result2 === null) {
    console.log(`2022 Images: 0`);
    console.log("No Sentinel-1 data found for 2022 period. Consider widening the date range.");
    console.log("C1");
    return;
  } else {
    area2_sqm = result2.area;
    num_images2 = result2.num_images;
    valid_pixels2 = result2.pixels;
    console.log(`2022 Images: ${num_images2} (Water Pixels: ${valid_pixels2})`);
  }

  // 3. Processing & 4. Calculation
  if (valid_pixels1 === 0 && valid_pixels2 === 0) {
    console.log("No valid water pixels found for either period after masking. May be dry or very strict threshold.");
    console.log("C2");
    return;
  }

  if (area1_sqm === null || isNaN(area1_sqm) || area2_sqm === null || isNaN(area2_sqm)) {
    console.log("Calculation resulted in null/NaN for water area.");
    console.log("C3");
    return;
  }

  console.log(`Water Area 2024 (Jan 4): ${area1_sqm / 1e6} km²`);
  console.log(`Water Area 2022 (Jan 5): ${area2_sqm / 1e6} km²`);

  // 5. Validation & Final Answer
  if (area1_sqm > area2_sqm) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
